package layout

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

// Record is the `record:` setting of .punt-labs/ethos.yaml. It decides where
// ethos writes the class-3 files that are not live files (DES-079).
type Record string

const (
	// RecordBlame is the default: class-3 files go to the machine-local archive
	// under TraceArchive, and git sees none of them.
	RecordBlame Record = "blame"
	// RecordFull writes class-3 files at their tracked paths under
	// .punt-labs/ethos/, as ethos did before DES-079.
	RecordFull Record = "full"
)

// TraceArchiveRel is the archive of the blame tier, relative to a repository
// root. A file keeps its path relative to .punt-labs/ethos/ inside it.
const TraceArchiveRel = ".punt-labs/local/ethos/trace"

// TraceArchive returns the trace archive of the checkout at root.
func TraceArchive(root string) string {
	return filepath.Join(root, filepath.FromSlash(TraceArchiveRel))
}

// ParseRecord returns the Record named by s. The empty string is the default,
// blame; any other unknown value is an error naming the accepted ones.
func ParseRecord(s string) (Record, error) {
	switch Record(s) {
	case "", RecordBlame:
		return RecordBlame, nil
	case RecordFull:
		return RecordFull, nil
	}
	return RecordBlame, fmt.Errorf("unknown record %q: must be %q or %q", s, RecordBlame, RecordFull)
}

// ReadRecord returns the record mode of the repository at root: the `record:`
// key of .punt-labs/ethos.yaml, else of the legacy .punt-labs/ethos/config.yaml,
// else blame. An empty root is blame. A config that cannot be read or parsed,
// or that names an unknown mode, is an error, never the default: a typo must
// not quietly put trace files in the tracked tree or out of it.
func ReadRecord(root string) (Record, error) {
	if root == "" {
		return RecordBlame, nil
	}
	for _, rel := range []string{".punt-labs/ethos.yaml", ".punt-labs/ethos/config.yaml"} {
		p := filepath.Join(root, filepath.FromSlash(rel))
		data, err := os.ReadFile(p)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return RecordBlame, fmt.Errorf("reading %s: %w", p, err)
		}
		var cfg struct {
			Record string `yaml:"record"`
		}
		if err := yaml.Unmarshal(data, &cfg); err != nil {
			return RecordBlame, fmt.Errorf("parsing %s: %w", p, err)
		}
		m, err := ParseRecord(cfg.Record)
		if err != nil {
			return RecordBlame, fmt.Errorf("%s: %w", p, err)
		}
		return m, nil
	}
	return RecordBlame, nil
}

