func writeConfig(t *testing.T, root, rel, body string) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestReadRecord(t *testing.T) {
	cases := []struct {
		name    string
		files   map[string]string
		want    Record
		wantErr string
	}{
		{"no config", nil, RecordBlame, ""},
		{"key absent", map[string]string{".punt-labs/ethos.yaml": "team: engineering\n"}, RecordBlame, ""},
		{"blame", map[string]string{".punt-labs/ethos.yaml": "record: blame\n"}, RecordBlame, ""},
		{"full", map[string]string{".punt-labs/ethos.yaml": "team: x\nrecord: full\n"}, RecordFull, ""},
		{"legacy path", map[string]string{".punt-labs/ethos/config.yaml": "record: full\n"}, RecordFull, ""},
		{"new path wins over legacy", map[string]string{
			".punt-labs/ethos.yaml":         "team: x\n",
			".punt-labs/ethos/config.yaml": "record: full\n",
		}, RecordBlame, ""},
		{"unknown value", map[string]string{".punt-labs/ethos.yaml": "record: everything\n"}, RecordBlame, `unknown record "everything"`},
		{"wrong case", map[string]string{".punt-labs/ethos.yaml": "record: Full\n"}, RecordBlame, `unknown record "Full"`},
		{"malformed yaml", map[string]string{".punt-labs/ethos.yaml": "record: [\n"}, RecordBlame, "parsing"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			root := t.TempDir()
			for rel, body := range c.files {
				writeConfig(t, root, rel, body)
			}
			got, err := ReadRecord(root)
			if c.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), c.wantErr) {
					t.Fatalf("ReadRecord = %q, %v; want error containing %q", got, err, c.wantErr)
				}
				return
			}
			if err != nil || got != c.want {
				t.Fatalf("ReadRecord = %q, %v; want %q", got, err, c.want)
			}
		})
	}
}

func TestReadRecordEmptyRootIsBlame(t *testing.T) {
	if got, err := ReadRecord(""); err != nil || got != RecordBlame {
		t.Fatalf("ReadRecord(\"\") = %q, %v; want blame", got, err)
	}
}

// The archive is class 3 for every path under it.
func TestTraceArchiveIsClassTrace(t *testing.T) {
	for _, rel := range []string{
		"missions/m-1/delegations/d-1/prompt.md",
		"missions/m-1/reflections.yaml",
		"missions/m-1/log-s-0000000000000000001-0000000000000000002.jsonl",
		"sessions/2026-01-01-s/audit-0000000000000000001-0000000000000000002.jsonl",
	} {
		p := filepath.ToSlash(filepath.Join(TraceArchiveRel, rel))
		if c, _, ok := Classify(p); !ok || c != Trace {
			t.Errorf("Classify(%s) = %v, %v; want trace", p, c, ok)
		}
	}
}

