package hook

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/punt-labs/ethos/v4/internal/audit"
	"github.com/punt-labs/ethos/v4/internal/layout"
	"github.com/punt-labs/ethos/v4/internal/testhelpers"
)

// gitOutput runs git in dir and returns its standard output.
func gitOutput(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := testhelpers.GitCommand(args...)
	cmd.Dir = dir
	cmd.Env = gitEnv(dir)
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git %s: %v", strings.Join(args, " "), err)
	}
	return string(out)
}

// writeMissionLive writes one live event line to a mission's live log.
func writeMissionLive(t *testing.T, repo, missionID, sessionID string, ts int64) {
	t.Helper()
	live := liveMissionLogPath(repo, missionID, sessionID)
	if err := os.MkdirAll(filepath.Dir(live), 0o700); err != nil {
		t.Fatal(err)
	}
	line := `{"ts":"` + audit.FormatLineTS(ts) + `","event":"update","actor":"a"}` + "\n"
	if err := os.WriteFile(live, []byte(line), 0o600); err != nil {
		t.Fatal(err)
	}
}

// Under blame, the default, the seal writes session and mission chunks into the
// trace archive, keeps their paths relative to .punt-labs/ethos, writes nothing
// to the tracked tree, and stages nothing.
func TestSealRepoBlameWritesToArchiveAndStagesNothing(t *testing.T) {
	repo := t.TempDir()
	initGitRepo(t, repo)
	const sid, mid = "sess-blame", "m-2026-07-20-001"
	writeLiveLines(t, repo, sid, 100, 200, 300)
	writeMissionLive(t, repo, mid, sid, 150)

	now := time.Date(2026, 7, 20, 12, 0, 0, 0, time.UTC)
	res, err := SealRepo(repo, now, SealOptions{})
	if err != nil {
		t.Fatalf("SealRepo: %v", err)
	}
	if res.SessionsSealed != 2 || res.LinesSealed != 4 {
		t.Errorf("res = %+v, want 2 units and 4 lines", res)
	}
	if res.ChunksStaged != 0 {
		t.Errorf("ChunksStaged = %d, want 0 under blame", res.ChunksStaged)
	}

	archive := layout.TraceArchive(repo)
	sessChunk := filepath.Join(archive, "sessions", "2026-07-20-"+sid, audit.SessionChunkFile(100, 300))
	missChunk := filepath.Join(archive, "missions", mid, audit.MissionChunkFile(sid, 150, 150))
	for _, p := range []string{sessChunk, missChunk} {
		if _, err := os.Stat(p); err != nil {
			t.Errorf("chunk not in the archive: %v", err)
		}
		rel, _ := filepath.Rel(repo, p)
		if c, _, ok := layout.Classify(rel); !ok || c != layout.Trace {
			t.Errorf("%s classified %v, %v; want trace", rel, c, ok)
		}
	}
	for _, tracked := range []string{
		filepath.Join(repo, ".punt-labs", "ethos", "sessions"),
		filepath.Join(repo, ".punt-labs", "ethos", "missions"),
	} {
		if _, err := os.Stat(tracked); err == nil {
			t.Errorf("blame wrote under the tracked tree: %s", tracked)
		}
	}
	if staged := gitOutput(t, repo, "diff", "--cached", "--name-only"); staged != "" {
		t.Errorf("blame staged files: %q", staged)
	}
	if got := gitOutput(t, repo, "status", "--porcelain", "--", ".punt-labs/ethos"); got != "" {
		t.Errorf("tracked tree changed under blame: %q", got)
	}
}

// Under full the seal is today's: chunks at their tracked paths, staged.
func TestSealRepoFullWritesTrackedAndStages(t *testing.T) {
	repo := t.TempDir()
	initFullRepo(t, repo)
	const sid, mid = "sess-full", "m-2026-07-20-002"
	writeLiveLines(t, repo, sid, 100, 200)
	writeMissionLive(t, repo, mid, sid, 150)

	now := time.Date(2026, 7, 20, 12, 0, 0, 0, time.UTC)
	res, err := SealRepo(repo, now, SealOptions{})
	if err != nil {
		t.Fatalf("SealRepo: %v", err)
	}
	if res.ChunksStaged != 2 {
		t.Errorf("ChunksStaged = %d, want 2 under full", res.ChunksStaged)
	}
	staged := gitOutput(t, repo, "diff", "--cached", "--name-only")
	for _, want := range []string{
		".punt-labs/ethos/sessions/2026-07-20-" + sid + "/" + audit.SessionChunkFile(100, 200),
		".punt-labs/ethos/missions/" + mid + "/" + audit.MissionChunkFile(sid, 150, 150),
	} {
		if !strings.Contains(staged, want) {
			t.Errorf("staged files lack %s:\n%s", want, staged)
		}
	}
	if _, err := os.Stat(layout.TraceArchive(repo)); err == nil {
		t.Error("full wrote into the trace archive")
	}
}

// An unknown record value stops the seal before it writes anything.
func TestSealRepoRefusesAnUnknownRecordValue(t *testing.T) {
	for name, seal := range map[string]func(repo string) error{
		"SealRepo": func(repo string) error {
			_, err := SealRepo(repo, time.Now().UTC(), SealOptions{})
			return err
		},
		"SealMission": func(repo string) error {
			_, err := SealMission(repo, "m-2026-07-20-003", time.Now().UTC(), SealOptions{})
			return err
		},
	} {
		t.Run(name, func(t *testing.T) {
			repo := t.TempDir()
			initGitRepo(t, repo)
			cfg := filepath.Join(repo, ".punt-labs", "ethos.yaml")
			if err := os.MkdirAll(filepath.Dir(cfg), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(cfg, []byte("record: everything\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			writeLiveLines(t, repo, "sess-bad-record", 100)
			err := seal(repo)
			if err == nil || !strings.Contains(err.Error(), `unknown record "everything"`) {
				t.Fatalf("seal = %v; want an error naming the unknown record value", err)
			}
			if _, statErr := os.Stat(layout.TraceArchive(repo)); statErr == nil {
				t.Error("the seal wrote into the archive despite the configuration error")
			}
			if _, statErr := os.Stat(filepath.Join(repo, ".punt-labs", "ethos", "sessions")); statErr == nil {
				t.Error("the seal wrote into the tracked tree despite the configuration error")
			}
		})
	}
}

// The blame seal is idempotent and incremental in the archive, like the
// tracked one: a second run seals only what is past the watermark.
func TestSealRepoBlameIncremental(t *testing.T) {
	repo := t.TempDir()
	initGitRepo(t, repo)
	const sid = "sess-blame-incr"
	now := time.Date(2026, 7, 20, 12, 0, 0, 0, time.UTC)
	writeLiveLines(t, repo, sid, 100, 200)
	if _, err := SealRepo(repo, now, SealOptions{}); err != nil {
		t.Fatalf("first seal: %v", err)
	}
	res, err := SealRepo(repo, now, SealOptions{})
	if err != nil || res.LinesSealed != 0 {
		t.Fatalf("second seal = %+v, %v; want nothing sealed", res, err)
	}
	writeLiveLines(t, repo, sid, 100, 200, 300)
