	_, repo, _ := auditMigrateEnv(t)
	dir := filepath.Join(audit.SealedSessionsBase(repo), "2026-01-01-sq")
	require.NoError(t, os.MkdirAll(dir, 0o700))
	chunk := filepath.Join(dir, audit.SessionChunkFile(100, 200))
	require.NoError(t, os.WriteFile(chunk, []byte("not json\\n"), 0o600))
	writeSqLive(t, repo)

	out, _, err := execHandler(t, "audit", "quarantine", chunk)
	require.NoError(t, err)
	assert.Contains(t, out, "kept in the local trace archive, nothing to stage")
	assert.NotContains(t, out, "staged, commit")
	assert.Empty(t, gitStdout(t, repo, "ls-files"))
	assert.Empty(t, gitStdout(t, repo, "diff", "--cached", "--name-only"))
	_, statErr := os.Stat(chunk + ".corrupt")
	assert.NoError(t, statErr, "the chunk is retired in place")
}

